create function pg_temp.force_proposal_audit_failure() returns trigger language plpgsql as $$ begin if new.event_type='proposal.approve' then raise exception using errcode='P0001',message='Fictional late proposal audit failure'; end if; return new; end; $$; create trigger fictional_proposal_audit_failure before insert on public.audit_logs for each row execute function pg_temp.force_proposal_audit_failure();
