select extensions.throws_ok('select public.review_project_proposal(''f7200000-0000-4000-8000-000000000001'',''f7400000-0000-4000-8000-000000000003'',(select (public.organization_proposal(''f7200000-0000-4000-8000-000000000001'',''f7400000-0000-4000-8000-000000000003'')->>''revision'')::bigint),(select access_revision::bigint from public.organization_proposal_context(''f7200000-0000-4000-8000-000000000001'')),(select assignment_revision::bigint from public.organization_proposal_context(''f7200000-0000-4000-8000-000000000001'')),''approve'',null,null)','P0001',null,'Late audit failure aborts approval');
select extensions.ok(public.organization_proposal('f7200000-0000-4000-8000-000000000001','f7400000-0000-4000-8000-000000000003')->>'status'='pending','Late failure leaves proposal pending');
select extensions.is((select count(*) from public.projects where name='Fictional network upgrade')::integer,1,'Late failure leaves no partial project');
reset role; drop trigger fictional_proposal_audit_failure on public.audit_logs;
select extensions.is((select count(*)::integer from storage.buckets where id='proposal-attachments' and not public and file_size_limit=10485760),1,'Private 10 MB bucket');
select extensions.is((select count(*)::integer from pg_policies where schemaname='storage' and tablename='objects'),0,'No user Storage policy bypass');
select * from extensions.finish(); rollback;
